  { id: 1, name: "Place de la Concorde (L-Hammam / Bd Lalla Yacout)", district: "Centre Ville", coordinates: [33.5912, -7.6134], taxiType: "Grand Taxi", destinations: ["Oulfa", "Maarif", "Ain Diab"] },
  { id: 2, name: "Station Casa-Port", district: "Casa-Port", coordinates: [33.6002, -7.6119], taxiType: "Grand & Petit Taxi", destinations: ["Ain Sebaa", "Sidi Bernoussi", "Mohammedia"] },
  { id: 3, name: "Station Casa-Voyageurs", district: "Casa-Voyageurs", coordinates: [33.5892, -7.5891], taxiType: "Grand & Petit Taxi", destinations: ["Centre Ville", "Hay Mohammadi", "Derb Sultan"] },
  { id: 4, name: "Station Garage Allal (Derb Sultan)", district: "Derb Sultan", coordinates: [33.5715, -7.6045], taxiType: "Grand Taxi", destinations: ["M [… 3,062 characters omitted] Sidi Maalouf (Near Technopark)", district: "Sidi Maalouf", coordinates: [33.5421, -7.6385], taxiType: "Grand Taxi", destinations: ["Bachkou", "Shorex", "Zenith"] },
  { id: 20, name: "Station Sidi Bernoussi - Tram Terminus", district: "Sidi Bernoussi", coordinates: [33.6152, -7.5089], taxiType: "Grand Taxi", destinations: ["Zone Industrielle", "Mohammedia"] }
];

const stationsFromDatabase = async () => {
  const docs = await Route.find({});
  const depots = new Map();
  docs.forEach((doc) => {
    if (!doc.location?.coordinates || depots.has(doc.depotName)) return;
    depots.set(doc.depotName, doc);
  });
  return [...depots.values()].map((doc, index) => ({
    id: index + 1,
    name: doc.depotName,
    district: doc.district,
    taxiType: doc.taxiType,
    coordinates: [doc.location.coordinates[1], doc.location.coordinates[0]],
    destinations: [],
  }));
};

app.get("/api/stations", async (req, res) => {
  const { type, district } = req.query;
  let result;
  try {
    result = await stationsFromDatabase();
  } catch {
    result = STATIONS;
  }
  if (type) {
    result = result.filter((s) => s.taxiType.toLowerCase().includes(type.toLowerCase()));
  }
  if (district) {
    result = result.filter((s) => s.district.toLowerCase().includes(district.toLowerCase()));
  }
  res.json(result);
});

app.get("/api/stations/:id", async (req, res) => {
  const id = parseInt(req.params.id, 10);
  let result;
  try {
    result = await stationsFromDatabase();
  } catch {
    result = STATIONS;
  }
  const station = result.find((s) => s.id === id);
  if (!station) return res.status(404).json({ error: "Station not found" });
  res.json(station);
});

// GeoJSON route catalogue (MongoDB, 2dsphere indexes): create/list/search/nearby
app.use("/api/routes", require("./routes/api"));

// Serve static frontend build
app.use(express.static(clientBuildDirectory));

// SPA fallback
app.use((req, res, next) => {
  if (req.method !== "GET" || req.path === "/api" || req.path.startsWith("/api/")) {
    return next();
  }
  const clientEntry = path.join(clientBuildDirectory, "index.html");
  if (!fs.existsSync(clientEntry)) return next();
  res.sendFile(clientEntry, (error) => {
    if (error && !res.headersSent) next();
  });
});

module.exports = app;
